CREATE FUNCTION public.save_organization_settings(_organization_id uuid,_name text,_description text,_settings jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_organization(_organization_id) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF length(trim(_name))<2 OR _settings->>'primary_color' !~ '^#[0-9a-fA-F]{6}$' OR _settings->>'secondary_color' !~ '^#[0-9a-fA-F]{6}$' THEN RAISE EXCEPTION 'Invalid settings'; END IF; UPDATE public.organizations SET name=left(trim(_name),120),description=left(_description,4000),updated_at=now() WHERE id=_organization_id; UPDATE public.organization_settings SET contact_email=_settings->>'email',phone=_settings->>'phone',address=_settings->>'address',postal_code=_settings->>'postal_code',city=_settings->>'city',location=_settings->>'location',responsible_name=_settings->>'responsible_name',organization_type=_settings->>'type',primary_color=_settings->>'primary_color',secondary_color=_settings->>'secondary_color',logo_path=nullif(_settings->>'logo_path',''),cover_path=nullif(_settings->>'cover_path',''),social_links=coalesce(_settings->'social_links','{}'::jsonb),updated_at=now() WHERE organization_id=_organization_id; INSERT INTO public.organization_audit_events(organization_id,actor_id,action) VALUES(_organization_id,auth.uid(),'organization.settings_changed'); END $$;
REVOKE ALL ON FUNCTION public.save_organization_settings(uuid,text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_organization_settings(uuid,text,text,jsonb) TO authenticated;
CREATE FUNCTION public.get_public_organization_settings(_organization_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('email',s.contact_email,'phone',s.phone,'address',s.address,'postal_code',s.postal_code,'city',s.city,'type',s.organization_type,'logo_path',s.logo_path,'cover_path',s.cover_path,'primary_color',s.primary_color,'secondary_color',s.secondary_color,'social_links',s.social_links) FROM public.organization_settings s WHERE s.organization_id=_organization_id AND public.organization_is_public(_organization_id) $$;
REVOKE ALL ON FUNCTION public.get_public_organization_settings(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.get_public_organization_settings(uuid) TO anon,authenticated;
CREATE FUNCTION public.platform_counts() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_platform_admin() THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN jsonb_build_object('organizations',(SELECT count(*) FROM public.organizations),'active',(SELECT count(*) FROM public.organizations WHERE status='active'),'suspended',(SELECT count(*) FROM public.organizations WHERE status='suspended'),'users',(SELECT count(*) FROM public.profiles),'tournaments',(SELECT count(*) FROM public.tournaments)); END $$;
REVOKE ALL ON FUNCTION public.platform_counts() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.platform_counts() TO authenticated;
CREATE FUNCTION public.set_organization_status(_organization_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_platform_admin() OR _status NOT IN ('active','suspended') THEN RAISE EXCEPTION 'Forbidden'; END IF; UPDATE public.organizations SET status=_status,updated_at=now() WHERE id=_organization_id; IF NOT FOUND THEN RAISE EXCEPTION 'Organization missing'; END IF; INSERT INTO public.organization_audit_events(organization_id,actor_id,action,details) VALUES(_organization_id,auth.uid(),'organization.status_changed',jsonb_build_object('status',_status)); END $$;
REVOKE ALL ON FUNCTION public.set_organization_status(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_organization_status(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.media_organization_id(_path text) RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF _path LIKE '%..%' OR position(E'\\' in _path)>0 THEN RETURN NULL; END IF; IF _path ~ '^organizations/[0-9a-fA-F-]{36}/(tournaments|photos|highlights|logos|covers)/[^/]+$' THEN BEGIN result:=split_part(_path,'/',2)::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN NULL; END; RETURN result; END IF; IF _path ~ '^(tournaments|photos|highlights)/[^/]+$' THEN SELECT id INTO result FROM public.organizations WHERE slug='foxes-darts'; RETURN result; END IF; RETURN NULL; END $$;
CREATE FUNCTION public.enforce_organization_settings_media() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN RAISE EXCEPTION 'Organization reassignment forbidden'; END IF; IF (NEW.logo_path IS NOT NULL AND public.media_organization_id(NEW.logo_path) IS DISTINCT FROM NEW.organization_id) OR (NEW.cover_path IS NOT NULL AND public.media_organization_id(NEW.cover_path) IS DISTINCT FROM NEW.organization_id) THEN RAISE EXCEPTION 'Media organization mismatch'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.enforce_organization_settings_media() FROM PUBLIC; CREATE TRIGGER organization_settings_media BEFORE UPDATE ON public.organization_settings FOR EACH ROW EXECUTE FUNCTION public.enforce_organization_settings_media();
CREATE OR REPLACE FUNCTION public.can_manage_tournament(_tournament_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.tournaments t JOIN public.organizations o ON o.id=t.organization_id WHERE t.id=_tournament_id AND o.status='active' AND (public.can_manage_organization(t.organization_id) OR EXISTS(SELECT 1 FROM public.organization_members m JOIN public.tournament_manager_assignments a ON a.user_id=m.user_id WHERE m.organization_id=t.organization_id AND m.user_id=auth.uid() AND m.role='TOURNAMENT_MANAGER' AND a.tournament_id=t.id))) $$;